import{_ as o,C as a,o as l,c as d,j as e,a as s,E as i,ak as c}from"./chunks/framework.sV-XtlWr.js";const h="/screenshots/create-issue-modal.png",u="/screenshots/cluster-issue-line.png",m="/screenshots/project-integration-binding.png",g="/screenshots/create-issue-required-fields.png",P=JSON.parse(`{"title":"Issue tracking (Jira)","description":"File a Jira issue from a failure with the fix plan as its body, keep it linked as the cluster's known issue, and keep its status in sync.","frontmatter":{"title":"Issue tracking (Jira)","description":"File a Jira issue from a failure with the fix plan as its body, keep it linked as the cluster's known issue, and keep its status in sync.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/issue-tracking.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/issue-tracking.html"}],["meta",{"property":"og:title","content":"Issue tracking (Jira) | Piwi Dashboard"}],["meta",{"property":"og:description","content":"File a Jira issue from a failure with the fix plan as its body, keep it linked as the cluster's known issue, and keep its status in sync."}]]},"headers":[],"relativePath":"features/issue-tracking.md","filePath":"features/issue-tracking.md","lastUpdated":1791666916000}`),p={name:"features/issue-tracking.md"};function f(k,t,b,y,w,v){const r=a("Needs"),n=a("DemoExamples");return l(),d("div",null,[t[0]||(t[0]=e("h1",{id:"issue-tracking-jira",tabindex:"-1"},[s("Issue tracking (Jira) "),e("a",{class:"header-anchor",href:"#issue-tracking-jira","aria-label":'Permalink to "Issue tracking (Jira)"'},"​")],-1)),i(r,{reporter:"",admin:""}),t[1]||(t[1]=c('<p>Piwi already ends an investigation with everything a ticket needs: a headline, the affected tests and owners, the diagnosis, a validated patch, the verify command. <strong>Create issue</strong> turns that into a Jira issue in one click: the body is the fix plan, the issue is linked back as the cluster&#39;s <em>known issue</em>, and from then on the key travels wherever the failure appears.</p><p>It is <strong>off until an <a href="/operate/integrations.html#connecting-jira-cloud">administrator connects Jira</a></strong>.</p><div class="doc-screenshot"><img src="'+h+'" alt="The Create issue modal on a failure cluster: an editable title, the Jira project and issue-type fields, include toggles, and a preview of the fix-plan body"></div><h2 id="what-it-does-exactly" tabindex="-1">What it does, exactly <a class="header-anchor" href="#what-it-does-exactly" aria-label="Permalink to &quot;What it does, exactly&quot;">​</a></h2><ul><li><strong>Create issue</strong> appears on a failure cluster, on a failing execution, on each inbox row (plus the <code>c</code> key and a <em>Create issues</em> button in the inbox bulk bar), and on a <a href="./bug-reports.html#filing-it-in-jira">bug report</a>. The cluster&#39;s <strong>Issue</strong> line and an execution&#39;s <strong>Cluster</strong> line offer <em>Create issue</em> and <em>Link an issue</em> until the cluster has a ticket, then name it, its summary on hover; the ⋮ menu offers <em>Open PROJ-123</em>.</li><li>The issue <strong>body is the fix plan</strong>, rendered to Atlassian Document Format: <em>What happened</em>, <em>Most likely</em>, <em>Evidence</em>, <em>What to do</em> (patch, locator replacement, verify command, reproduce steps), <em>Related issues</em> fixed before and <em>Links</em> back to Piwi. Every section degrades independently.</li><li>Each issue carries the labels <code>piwi</code>, <code>piwi-cluster-&lt;id&gt;</code> and <code>piwi-fp-&lt;hash&gt;</code> and a <code>Piwi-Cluster: &lt;id&gt;</code> trailer, so a JQL filter finds every Piwi-filed issue.</li><li><strong>Filing is deduped by cluster</strong> — a second click, a duplicate event, a <a href="./issue-automation.html">rule</a> or a create from another of its executions names the issue already filed; once that link is removed or the issue is Done, the next create files a new one, and a Done issue stays linked. Before creating, the modal surfaces any issue that already tracks the failure (a pinned link, a matching label, or a <em>fixed-before</em> match) and leads with <em>link it instead</em>.</li><li>Creating an issue is a <strong>durable outbox action</strong>: attempted immediately, retried with backoff if Jira is down (the cluster and execution pages show <em>Filing queued</em>, with a retry), and recorded: the cluster&#39;s <strong>Activity</strong> lists each write Piwi makes to the issue. A create Jira refuses outright (a missing or invalid field) fails at once, with Jira&#39;s reason atop the modal and on the Issue or Cluster line; creating again replaces it.</li></ul><h2 id="the-key-travels" tabindex="-1">The key travels <a class="header-anchor" href="#the-key-travels" aria-label="Permalink to &quot;The key travels&quot;">​</a></h2><p>A cluster&#39;s <strong>known issue</strong> is its most recently linked ticket; earlier ones stay among its links, which an execution&#39;s <em>Details</em> also lists. Its key follows the failure everywhere:</p><ul><li>the cluster&#39;s <strong>Issue</strong> line and a failing execution&#39;s <strong>Cluster</strong> line, the <strong>inbox row</strong> and the execution&#39;s row in the <strong>run&#39;s test list</strong> show the key with its status; the <strong>search</strong> (Ctrl K) finds the cluster from the key;</li><li><code>cluster.new</code>, <code>cluster.fixed</code> and <code>cluster.regressed</code> <strong>Slack</strong> messages name it, as does the <code>cluster.new</code> email;</li><li>the <strong>pull-request feedback</strong> comment says <em>tracked in PROJ-123</em> on each failure whose cluster has one;</li><li>the <strong>fix plan</strong> lists it under <em>Links</em>, and the <code>get_cluster</code> / <code>get_fix_plan</code> MCP tools return it.</li></ul><div class="doc-screenshot"><img src="'+u+'" alt="A failure cluster&#39;s situation block with its Issue line naming the Jira issue the cluster is tracked in"></div><h2 id="keep-the-ticket-honest" tabindex="-1">Keep the ticket honest <a class="header-anchor" href="#keep-the-ticket-honest" aria-label="Permalink to &quot;Keep the ticket honest&quot;">​</a></h2><p>Once a cluster carries a known issue, Piwi keeps the two in step. A background sync (<a href="/reference/configuration.html"><code>PIWI_INTEGRATIONS_SYNC_MINUTES</code></a>, default 15 min) reads each tracked issue back and caches its status, title and assignee (open clusters every sweep, resolved ones daily). Per-project <strong>policies</strong>, all <strong>off by default</strong>, each a durable deduped outbox action, write back as the cluster evolves:</p><table tabindex="0"><thead><tr><th>When Piwi observes</th><th>What Piwi does</th></tr></thead><tbody><tr><td>A cluster&#39;s <strong>fix lands</strong> (stopped failing or diagnosis verified)</td><td>Comments <em>Fix landed in run #N …</em>, and with <em>transition on fix</em> moves the issue.</td></tr><tr><td>A cluster <strong>regresses</strong></td><td>Comments <em>Regressed in run #N …</em>, and optionally reopens the issue.</td></tr><tr><td><strong>New occurrences</strong> on an open ticket</td><td>At most one note a day or a week: <em>Still failing — +N occurrences in 3 runs …</em>, with what is new.</td></tr><tr><td>A cluster is <strong>merged</strong></td><td>With <em>comment on merge</em>, notes it on both issues; the survivor inherits the links.</td></tr><tr><td>The <strong>ticket moves to Done</strong></td><td>With <em>resolve on close</em>, resolves the cluster unless its fix regressed. Otherwise, once the latest finished run no longer fails and the fix did not regress, the next step is <em>Mark the cluster resolved — PROJ-123 is Done</em>; while it fails, the Issue or Cluster line offers <em>File a new issue</em>.</td></tr><tr><td>The <strong>ticket is reopened</strong></td><td>With <em>reopen on ticket reopen</em>, reopens a resolved cluster with a note.</td></tr></tbody></table><p>Both status policies act on a <strong>move</strong> of the ticket, so a cluster a person reopened or resolved stays as they set it.</p><p>Every comment is written in the <a href="#language">ticket&#39;s language</a>, for the <a href="./issue-automation.html#the-runs-that-write">runs that write</a>; <a href="./issue-automation.html">Issue automation</a> adds diagnosis comments and description updates. A Jira admin can register an optional <a href="/operate/integrations.html#registering-the-inbound-webhook">inbound webhook</a> so a close or reopen shows at once; it only refreshes a link. The failure inbox gains a <strong>Needs ticket</strong> queue — open clusters on the default branch, older than the binding&#39;s age (default 2 days), with no issue.</p><h2 id="the-project-binding" tabindex="-1">The project binding <a class="header-anchor" href="#the-project-binding" aria-label="Permalink to &quot;The project binding&quot;">​</a></h2><p>A Project admin or an administrator binds the project under <strong>Project → Settings → Issue tracker</strong>: the connection, Jira project and issue type, default labels and assignee, the <a href="#language">ticket language</a>, what a ticket carries, the policies above, and <strong>owner routes</strong> — mapping a cluster&#39;s owner (<code>@acme/checkout</code>, an email) to a Jira project, component, assignee and labels. The create-issue draft picks the first matching route.</p><div class="doc-screenshot"><img src="'+m+'" alt="The project&#39;s Issue tracker settings: connection, Jira project and issue type, labels, the runs that write to the ticket, sync-policy switches, an owner-routes table, and automatic creation with one rule"></div><h2 id="required-jira-fields" tabindex="-1">Required Jira fields <a class="header-anchor" href="#required-jira-fields" aria-label="Permalink to &quot;Required Jira fields&quot;">​</a></h2><p>A Jira project can require fields on its create screen, such as a <em>Severity</em> or a <em>Team</em>. Piwi reads the issue type&#39;s create screen and asks for every required field Jira does not fill:</p><ul><li>The project binding&#39;s <strong>Jira fields</strong> block lists them. A value set there fills every issue filed from the project; <em>Set a default for another field</em> adds an optional one.</li><li>The create modal shows them under <strong>Required by Jira</strong>, prefilled from those defaults, and keeps <em>Create</em> disabled until each has a value. A value Jira lists no choices for, such as a team, is typed as its id.</li><li>The <a href="/reference/mcp-tools.html#create_issue"><code>create_issue</code> MCP tool</a> refuses early, naming each missing field, its id and what it takes; an agent passes them in <code>fields</code>.</li></ul><p>Transitions are checked the same way: for <em>transition on fix</em> and the reopen transition, the binding suggests the transitions an issue offers and asks for their required fields, such as a <em>Resolution</em>; a move that would leave one empty fails at once, naming it. A requirement no screen shows, such as a workflow validator, comes back as Jira&#39;s refusal naming the field.</p><div class="doc-screenshot"><img src="'+g+'" alt="The Create issue modal with a Required by Jira block: Severity prefilled with Major from the project settings, an empty Team field, and the footer saying Jira still needs Team"></div><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>A connected <strong>Jira Cloud</strong> site — see <a href="/operate/integrations.html#connecting-jira-cloud">Operate → Integrations</a>.</li><li><strong><code>PIWI_SITE_URL</code></strong> set, so the issue body&#39;s links resolve back to the dashboard.</li><li>The <strong>Contributor</strong> <a href="/operate/project-access.html#what-each-role-can-do">role</a> or above to create or link an issue; anyone who reads the project sees the key and status.</li></ul><h2 id="enable-it" tabindex="-1">Enable it <a class="header-anchor" href="#enable-it" aria-label="Permalink to &quot;Enable it&quot;">​</a></h2><p>The modal prefills its fields from the <a href="#the-project-binding">project binding</a>, else offers pickers over the connected site; toggles choose what the body carries (diagnosis and patch on, <a href="/features/share-links.html">share link</a> off). From an AI agent, the <a href="/reference/mcp-tools.html#create_issue"><code>create_issue</code> MCP tool</a> files the same ticket once the binding names a Jira project and issue type.</p><h2 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h2><p>A ticket&#39;s language follows its <strong>destination</strong>: the <strong>project binding</strong>&#39;s language, else the <strong>connection</strong>&#39;s default (a French Atlassian site can default every ticket to French), else <strong>English</strong>. The create modal offers a per-issue <em>Language</em> select and the <code>create_issue</code> MCP tool takes a <code>locale</code>. <strong>English and French ship.</strong></p><p>Only the copy <strong>Piwi authors</strong> is translated: headings, fact labels, policy comments, dates and counts. Your data (test titles, errors, locators, paths, commands, the patch) is <strong>never</strong> translated. The model&#39;s prose follows the separate <a href="/features/ai-diagnosis.html#response-language">AI response-language setting</a>, so a French ticket&#39;s <em>Most likely</em> section reads in French too.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Jira Cloud only</strong> (REST v3, email + API token).</li><li>A ticket&#39;s body is a <strong>snapshot</strong> at creation, unless <a href="./issue-automation.html#comments-and-description-updates">description updates</a> are on for an issue Piwi filed.</li><li>The dashboard&#39;s deterministic sentences (headline, story, clue, state line) are <strong>English templates</strong>, so they stay English even in a French ticket.</li><li>Attachments honor the <a href="/features/offline-export.html">export size budget</a>; the trace is never attached.</li></ul><h2 id="try-it-in-the-demo" tabindex="-1">Try it in the demo <a class="header-anchor" href="#try-it-in-the-demo" aria-label="Permalink to &quot;Try it in the demo&quot;">​</a></h2>',32)),i(n),t[2]||(t[2]=e("h2",{id:"related",tabindex:"-1"},[s("Related "),e("a",{class:"header-anchor",href:"#related","aria-label":'Permalink to "Related"'},"​")],-1)),t[3]||(t[3]=e("ul",null,[e("li",null,[e("a",{href:"./issue-automation.html"},"Issue automation"),s(": tickets filed by rule")]),e("li",null,[e("a",{href:"./failure-clusters.html"},"Failure clusters & the inbox"),s(": what a ticket tracks")])],-1))])}const T=o(p,[["render",f]]);export{P as __pageData,T as default};
